float r_mag = std::sqrt(r_sq);

if (r_mag > 0.0f && r_mag < h) {
    float r_h = r_mag / h;
    float w = spikyLap * (h - r_mag) * (h - r_mag) * (h - r_mag) / (6.0f * PI * h * h * h * h * h * r_mag);

    glm::vec3 v_rel = pj->velocity - pi->velocity;
    glm::vec3 force = mass * viscosity * w * v_rel;

    return force;
}
return glm::vec3(0.0f);

